<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type Option = { id: string; label: string; risk: string }
type MatchContext = { matchday: number; rival: string; minute: number; teamGoals: number; rivalGoals: number; stakes: string; isDecisive: boolean }
type Event = { id: string; category: string; title: string; description: string; miniGame: string; options: Option[]; match?: MatchContext; requiredSelections?: number }
type Player = { name: string; nationality: string; shirtNumber: number; position: string; archetype: string; personality: string; age: number; overall: number; form: number; energy: number; reputation: number; money: number; pace: number; shooting: number; passing: number; dribbling: number; defending: number; physical: number; goalkeeping: number; skillMoves: number; weakFoot: number; morale: number; coachRelation: number; fansRelation: number; mediaRelation: number; injuryRisk: number; goals: number; assists: number; appearances: number; ratingTotal: number }
type Row = { club: string; played: number; points: number; goalDifference: number }
type Career = { season: number; currentClub: string; currentLeague: string; currentMatchday: number; seasonComplete: boolean; player: Player; activeEvent?: Event; table: Row[]; timeline: string[]; trophies: string[] }
type Club = { name: string; league: string; region: string }
type World = { nationalities: string[]; leagues: { name: string; region: string }[]; clubs: Club[] }
const api = 'http://localhost:5098/api'; const career = ref<Career | null>(null); const busy = ref(false); const error = ref('')
const world = ref<World>({ nationalities: [], leagues: [], clubs: [] })
const profile = ref({ name: '', nationality: 'México', shirtNumber: 10, league: 'Liga MX', club: 'América', position: 'Mediocampista', archetype: 'Equilibrado', personality: 'Profesional' })
const clubsForLeague = computed(() => world.value.clubs.filter(c => c.league === profile.value.league))
const average = computed(() => !career.value?.player.appearances ? '—' : (career.value.player.ratingTotal / career.value.player.appearances).toFixed(2))
const meter = ref(0); const meterDirection = ref(1)
const preseasonChoices = ref<string[]>([])
const requiredSelections = computed(() => career.value?.activeEvent?.requiredSelections ?? 1)
onMounted(async () => { window.setInterval(() => { meter.value += meterDirection.value * 7; if (meter.value >= 100 || meter.value <= 0) meterDirection.value *= -1 }, 80); try { world.value = await request('/world', { method: 'GET' }); profile.value.nationality = world.value.nationalities[0] ?? profile.value.nationality; profile.value.league = world.value.leagues[0]?.name ?? profile.value.league; syncClub() } catch (e) { error.value = message(e) }; const saved = localStorage.getItem('camino-career'); if (saved) try { career.value = normalizeCareer(JSON.parse(saved)) } catch { localStorage.removeItem('camino-career') } })
function normalizeCareer(value: Career): Career { return { ...value, trophies: value.trophies ?? [], table: value.table ?? [], timeline: value.timeline ?? [] } }
function syncClub() { profile.value.club = clubsForLeague.value[0]?.name ?? '' }
function save(value: Career) { career.value = normalizeCareer(value); localStorage.setItem('camino-career', JSON.stringify(career.value)) }
async function createCareer() { busy.value = true; error.value = ''; try { save(await request('/career', { method: 'POST', body: JSON.stringify(profile.value) })) } catch (e) { error.value = message(e) } finally { busy.value = false } }
async function choose(optionId: string) { if (!career.value) return; busy.value = true; error.value = ''; const skillScore = career.value.activeEvent?.match?.isDecisive ? Math.round(100 - Math.abs(50 - meter.value) * 2) : undefined; try { save(await request('/career/decision', { method: 'POST', body: JSON.stringify({ career: career.value, optionId, skillScore }) })) } catch (e) { error.value = message(e) } finally { busy.value = false } }
function togglePreseason(id: string) { if (preseasonChoices.value.includes(id)) preseasonChoices.value = preseasonChoices.value.filter(choice => choice !== id); else if (preseasonChoices.value.length < requiredSelections.value) preseasonChoices.value.push(id) }
async function submitPreseason() { if (preseasonChoices.value.length !== requiredSelections.value) return; await choose(preseasonChoices.value.join(',')); preseasonChoices.value = [] }
async function advance() { if (!career.value) return; busy.value = true; error.value = ''; const path = career.value.seasonComplete ? '/career/advance-season' : '/career/advance'; try { save(await request(path, { method: 'POST', body: JSON.stringify(career.value) })) } catch (e) { error.value = message(e) } finally { busy.value = false } }
async function request(path: string, init: RequestInit) { const response = await fetch(api + path, { ...init, headers: { 'Content-Type': 'application/json' } }); if (!response.ok) throw new Error((await response.json()).error ?? 'No se pudo conectar al motor.'); return response.json() }
function message(error: unknown) { return error instanceof Error ? error.message : 'Error inesperado' }
function restart() { localStorage.removeItem('camino-career'); career.value = null }
</script>
<template><main>
  <section v-if="!career" class="onboarding"><p class="eyebrow">CAMINO A LA GLORIA</p><h1>Tu carrera empieza en una decisión.</h1><p class="lead">Cada decisión nace de un partido, una tabla y una temporada que sigue viva sin ti.</p>
    <form @submit.prevent="createCareer" class="creator"><label>Nombre<input v-model="profile.name" placeholder="Tu nombre" maxlength="28" required /></label><label>Nacionalidad<select v-model="profile.nationality" :disabled="!world.nationalities.length"><option v-for="n in world.nationalities" :key="n" :value="n">{{ n }}</option></select></label><label>Número<input v-model.number="profile.shirtNumber" type="number" min="1" max="99" required /></label><label>Liga<select v-model="profile.league" :disabled="!world.leagues.length" @change="syncClub"><option v-for="league in world.leagues" :key="league.name" :value="league.name">{{ league.name }} · {{ league.region }}</option></select></label><label>Equipo<select v-model="profile.club" :disabled="!clubsForLeague.length"><option v-for="club in clubsForLeague" :key="club.name" :value="club.name">{{ club.name }}</option></select></label><label>Posición<select v-model="profile.position"><option>Portero</option><option>Defensa</option><option>Mediocampista</option><option>Extremo</option><option>Delantero</option></select></label><label>Arquetipo<select v-model="profile.archetype"><option>Equilibrado</option><option>Talento</option><option>Incansable</option><option>Líder</option></select></label><label>Personalidad<select v-model="profile.personality"><option>Profesional</option><option>Ambicioso</option><option>Sereno</option><option>Carismático</option></select></label><button :disabled="busy || !world.leagues.length || !clubsForLeague.length">{{ busy ? 'Preparando el mundo...' : 'Empezar carrera' }}</button></form><p v-if="error" class="error">{{ error }}</p>
  </section>
  <template v-else><header class="topbar"><div><p class="eyebrow">TEMPORADA {{ career.season }} · JORNADA {{ career.currentMatchday }}</p><h2>{{ career.currentClub }}</h2><span>{{ career.currentLeague }}</span></div><button class="quiet" @click="restart">Nueva carrera</button></header>
    <section class="player-card"><div class="overall"><strong>{{ career.player.overall }}</strong><span>MEDIA</span></div><div><p class="eyebrow">{{ career.player.nationality }} · #{{ career.player.shirtNumber }} · {{ career.player.position }} · {{ career.player.age }} AÑOS</p><h1>{{ career.player.name }}</h1><p>Filigranas {{ '★'.repeat(career.player.skillMoves) }} · Pierna mala {{ '★'.repeat(career.player.weakFoot) }}</p></div><div class="metrics"><span>Forma <b>{{ career.player.form }}</b></span><span>Energía <b>{{ career.player.energy }}</b></span><span>Moral <b>{{ career.player.morale }}</b></span><span>Riesgo lesión <b>{{ career.player.injuryRisk }}</b></span></div></section>
    <section class="attribute-card"><p class="eyebrow">ATRIBUTOS DEL JUGADOR</p><div class="attribute-grid"><span>RIT <b>{{ career.player.pace }}</b></span><span>TIR <b>{{ career.player.shooting }}</b></span><span>PAS <b>{{ career.player.passing }}</b></span><span>REG <b>{{ career.player.dribbling }}</b></span><span>DEF <b>{{ career.player.defending }}</b></span><span>FIS <b>{{ career.player.physical }}</b></span><span v-if="career.player.position === 'Portero'">POR <b>{{ career.player.goalkeeping }}</b></span><span>DT <b>{{ career.player.coachRelation }}</b></span><span>Afición <b>{{ career.player.fansRelation }}</b></span><span>Prensa <b>{{ career.player.mediaRelation }}</b></span></div></section>
    <section class="grid"><article class="event-card"><p class="eyebrow">{{ career.activeEvent ? career.activeEvent.category : career.seasonComplete ? 'TEMPORADA TERMINADA' : 'CALENDARIO' }}</p><h2>{{ career.activeEvent?.title ?? (career.seasonComplete ? 'Es momento de cerrar el año' : 'Avanza hasta la próxima situación') }}</h2><p>{{ career.activeEvent?.description ?? (career.seasonComplete ? 'Tus estadísticas y posición final quedarán registradas.' : 'El motor simulará jornadas hasta encontrar un partido de alto impacto.') }}</p><div v-if="career.activeEvent?.match" class="match-context"><span>JORNADA {{ career.activeEvent.match.matchday }} · MIN {{ career.activeEvent.match.minute }}</span><strong>{{ career.currentClub }} {{ career.activeEvent.match.teamGoals }} — {{ career.activeEvent.match.rivalGoals }} {{ career.activeEvent.match.rival }}</strong><small>{{ career.activeEvent.match.stakes }}</small></div><div v-if="career.activeEvent?.match?.isDecisive" class="timing-game"><span>MINIJUEGO DE PRECISIÓN · DETÉN LA DECISIÓN EN LA ZONA VERDE</span><div class="meter"><i :style="{ left: meter + '%' }"></i><b></b></div><small>Tu precisión actual: {{ Math.round(100 - Math.abs(50 - meter) * 2) }}%</small></div><div v-if="career.activeEvent" class="minigame">MINIJUEGO: {{ career.activeEvent.miniGame }} · {{ career.activeEvent.category === 'Pretemporada' ? 'elige una rutina de tres' : 'elige una acción' }}</div><div class="choices" v-if="career.activeEvent?.category === 'Pretemporada'"><button v-for="option in career.activeEvent.options" :key="option.id" :class="{ selected: preseasonChoices.includes(option.id) }" :disabled="busy" @click="togglePreseason(option.id)">{{ option.label }} <small>{{ option.risk }}</small></button><button :disabled="busy || preseasonChoices.length !== requiredSelections" @click="submitPreseason">Confirmar rutina ({{ preseasonChoices.length }}/{{ requiredSelections }})</button></div><div class="choices" v-else-if="career.activeEvent"><button v-for="option in career.activeEvent.options" :key="option.id" :disabled="busy" @click="choose(option.id)">{{ option.label }} <small>Riesgo {{ option.risk }}</small></button></div><button v-else :disabled="busy" @click="advance">{{ busy ? 'Simulando...' : career.seasonComplete ? 'Iniciar siguiente temporada' : 'Avanzar al próximo evento' }}</button><p v-if="error" class="error">{{ error }}</p></article><article class="stats-card"><p class="eyebrow">CARRERA</p><div class="stat-row"><span>PJ</span><b>{{ career.player.appearances }}</b></div><div class="stat-row"><span>Goles</span><b>{{ career.player.goals }}</b></div><div class="stat-row"><span>Asistencias</span><b>{{ career.player.assists }}</b></div><div class="stat-row"><span>Promedio</span><b>{{ average }}</b></div><div class="stat-row"><span>Títulos</span><b>{{ career.trophies.length }}</b></div></article><article class="table-card"><p class="eyebrow">{{ career.currentLeague }}</p><ol><li v-for="(row,index) in career.table" :key="row.club"><span>{{ index + 1 }}. {{ row.club }} <small>{{ row.played }} PJ</small></span><b>{{ row.points }} pts</b></li></ol></article></section>
    <section class="timeline"><p class="eyebrow">MAPA DE CARRERA</p><div v-for="(item,index) in career.timeline.slice().reverse()" :key="index" class="timeline-item"><i></i>{{ item }}</div></section>
  </template>
</main></template>
